<template><div class="app-container"><el-card><template #header>{{ props.title }}</template><el-form :inline="true" :model="query"><el-form-item v-for="field in props.queryFields" :key="field.prop" :label="field.label"><el-input v-model="query[field.prop]" clearable @keyup.enter="search" /></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="resetQuery">重置</el-button><el-button type="success" @click="openCreate">新增</el-button></el-form-item></el-form><el-table v-loading="loading" :data="rows" border><el-table-column type="index" width="55" /><el-table-column v-for="column in props.columns" :key="column.prop" :prop="column.prop" :label="column.label" :min-width="column.width || 130"><template #default="scope">{{ display(scope.row[column.prop]) }}</template></el-table-column><el-table-column label="操作" width="140"><template #default="scope"><el-button link type="primary" @click="openEdit(scope.row)">编辑</el-button><el-button link type="danger" @click="remove(scope.row)">删除</el-button></template></el-table-column></el-table><Pagination v-show="total > 0" v-model:page="page.current" v-model:limit="page.size" :total="total" @pagination="load" /></el-card><el-dialog v-model="dialog.open" :title="dialog.title" width="560px"><el-form :model="form" label-width="105px"><el-form-item v-for="field in props.formFields" :key="field.prop" :label="field.label"><el-input-number v-if="field.type === 'number'" v-model="form[field.prop]" style="width:100%" /><el-input v-else v-model="form[field.prop]" :type="field.type === 'textarea' ? 'textarea' : 'text'" /></el-form-item></el-form><template #footer><el-button @click="dialog.open=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">确定</el-button></template></el-dialog></div></template>
<script setup>
import { pageConfigs, toCrudProps } from '@/views/pageConfig'; import { useCrudPage } from '@/views/useCrudPage'; import { pageApi } from './api'
const props = toCrudProps(pageConfigs.role, pageApi, { fetch: 'roles', save: 'saveRole', update: 'updateRole', remove: 'deleteRole' }); const { loading, saving, rows, total, query, page, form, dialog, display, load, search, resetQuery, openCreate, openEdit, submit, remove } = useCrudPage(props)
</script>
